import { XBookmarksResultSchema } from '../../types/x-bookmarks';
import type { BoardPage } from './boardPage';

export const isXBookmarkUrl = (raw: string): boolean => {
  try {
    const url = new URL(raw);
    return (
      url.protocol === 'https:' &&
      ['x.com', 'www.x.com'].includes(url.hostname) &&
      !url.port &&
      !url.username &&
      !url.password &&
      !url.search &&
      !url.hash &&
      /^\/i\/bookmarks\/?$/.test(url.pathname)
    );
  } catch {
    return false;
  }
};

export const xPage = (
  input: unknown,
  cursor: string | null,
  expectedAccountId: string,
): BoardPage => {
  const result = XBookmarksResultSchema.parse(input);
  if (result.status !== 'ok')
    throw new Error('X did not return a complete bookmark page');
  if (result.account.id !== expectedAccountId)
    throw new Error(
      'The connected X account changed before the bookmark page was saved',
    );
  if (result.nextCursor !== null && result.nextCursor === cursor)
    throw new Error('X returned a repeated page cursor');
  return {
    remoteId: `bookmarks:${result.account.id}`,
    title: `@${result.account.username} bookmarks`,
    cursor: result.nextCursor,
    isComplete: result.nextCursor === null,
    references: result.bookmarks.map((bookmark) => ({
      provider: 'x',
      remoteId: bookmark.id,
      title: `@${bookmark.author.username} on X`,
      text: [
        `Author: ${bookmark.author.name ?? bookmark.author.username} (@${bookmark.author.username})`,
        bookmark.text,
        ...bookmark.links,
        ...bookmark.media.map(
          (media) =>
            `${media.representation === 'video-cover' ? 'Video cover' : 'Image'}${media.altText ? `: ${media.altText}` : ''}`,
        ),
        ...(bookmark.unavailableVideoCount
          ? [
              `${bookmark.unavailableVideoCount} video attachment(s) have no available cover. Videos are not downloaded.`,
            ]
          : []),
      ].join('\n'),
      url: `https://x.com/${bookmark.author.username}/status/${bookmark.id}`,
      media: [],
      remoteImages: bookmark.media.map((media) => media.url),
      remoteImageRepresentations: bookmark.media.map(
        (media) => media.representation,
      ),
    })),
  };
};
